#include "module_controls.h"
#include <string.h>
static int copy(char *d,size_t cap,const char *s,int required){size_t n;if(!s)s="";n=strlen(s);if((required&&!n)||n>=cap)return 0;memcpy(d,s,n+1);return 1;}
static int valid_id(const char *s){size_t i;if(!s||!s[0])return 0;for(i=0;s[i];i++){char x=s[i];if(!((x>='a'&&x<='z')||(x>='0'&&x<='9')||x=='-'||x=='_'||x=='.'))return 0;}return 1;}
void rtp_module_controls_init(rtp_module_control_catalogue *c){if(c)memset(c,0,sizeof(*c));}
const rtp_module_control *rtp_module_control_find(const rtp_module_control_catalogue *c,const char *id){size_t i;if(!c||!id||c->count>RTP_CONTROL_MAX)return NULL;for(i=0;i<c->count;i++)if(!strcmp(c->controls[i].id,id))return &c->controls[i];return NULL;}
int rtp_module_control_register(rtp_module_control_catalogue *c,const rtp_control_descriptor *d){rtp_module_control x;size_t i;if(!c||!d||!valid_id(d->id)||!valid_id(d->module_id)||!d->title||!d->description)return RTP_CONTROL_INVALID_ARGUMENT;if(c->count>RTP_CONTROL_MAX)return RTP_CONTROL_INVALID_ARGUMENT;if(c->count==RTP_CONTROL_MAX)return RTP_CONTROL_CAPACITY;if(rtp_module_control_find(c,d->id))return RTP_CONTROL_DUPLICATE;if(d->kind<RTP_CONTROL_TOGGLE||d->kind>RTP_CONTROL_NUMBER)return RTP_CONTROL_INVALID_DESCRIPTOR;if(d->kind==RTP_CONTROL_SELECT){if(!d->options||!d->option_count||d->option_count>RTP_CONTROL_OPTIONS_MAX)return RTP_CONTROL_INVALID_DESCRIPTOR;}else if(d->option_count||d->options)return RTP_CONTROL_INVALID_DESCRIPTOR;if(d->kind==RTP_CONTROL_SLIDER||d->kind==RTP_CONTROL_NUMBER){if(d->minimum>d->maximum||d->step<=0)return RTP_CONTROL_INVALID_DESCRIPTOR;}else if(d->minimum||d->maximum||d->step)return RTP_CONTROL_INVALID_DESCRIPTOR;memset(&x,0,sizeof(x));if(!copy(x.id,sizeof(x.id),d->id,1)||!copy(x.title,sizeof(x.title),d->title,1)||!copy(x.description,sizeof(x.description),d->description,0)||!copy(x.module_id,sizeof(x.module_id),d->module_id,1))return RTP_CONTROL_INVALID_DESCRIPTOR;x.kind=d->kind;x.minimum=d->minimum;x.maximum=d->maximum;x.step=d->step;x.read_only=d->read_only;for(i=0;i<d->option_count;i++){size_t j;if(!copy(x.options[i].value,sizeof(x.options[i].value),d->options[i].value,1)||!copy(x.options[i].label,sizeof(x.options[i].label),d->options[i].label,1))return RTP_CONTROL_INVALID_DESCRIPTOR;for(j=0;j<i;j++)if(!strcmp(x.options[j].value,x.options[i].value))return RTP_CONTROL_INVALID_DESCRIPTOR;}x.option_count=d->option_count;c->controls[c->count++]=x;return RTP_CONTROL_OK;}
static int valid_value(const rtp_module_control *c,long n,const char *s){size_t i;if(c->kind==RTP_CONTROL_TOGGLE)return n==0||n==1;if(c->kind==RTP_CONTROL_SELECT){if(!s)return 0;for(i=0;i<c->option_count;i++)if(!strcmp(c->options[i].value,s))return 1;return 0;}if(n<c->minimum||n>c->maximum)return 0;return ((n-c->minimum)%c->step)==0;}
int rtp_module_control_read(const rtp_module_control_catalogue *c,const char *id,const rtp_control_backend *b,void *ctx,long *n,char *s,size_t cap){const rtp_module_control *d=rtp_module_control_find(c,id);if(!d)return RTP_CONTROL_NOT_FOUND;if(!b||!b->read||!n||!s||!cap)return RTP_CONTROL_INVALID_ARGUMENT;if(b->read(ctx,id,n,s,cap)!=0)return RTP_CONTROL_BACKEND_ERROR;if(!valid_value(d,*n,s))return RTP_CONTROL_INVALID_VALUE;return RTP_CONTROL_OK;}
int rtp_module_control_write(const rtp_module_control_catalogue *c,const char *id,const rtp_control_backend *b,void *ctx,long n,const char *s){const rtp_module_control *d=rtp_module_control_find(c,id);if(!d)return RTP_CONTROL_NOT_FOUND;if(d->read_only)return RTP_CONTROL_READ_ONLY;if(!b||!b->write)return RTP_CONTROL_INVALID_ARGUMENT;if(!valid_value(d,n,s))return RTP_CONTROL_INVALID_VALUE;return b->write(ctx,id,n,s)==0?RTP_CONTROL_OK:RTP_CONTROL_BACKEND_ERROR;}
